<?php session_start(); require_once __DIR__.'/../app/config/config.php'; requireLogin(); $type=$_GET['type']??'all'; $rows=$pdo->query("SELECT s.nis AS NIS,s.name AS Siswa,COALESCE(s.class_name,'-') AS Kelas,a.subject AS Mapel,ROUND((a.knowledge_score+a.skill_score)/2,1) AS Nilai,CONCAT(s.attendance_rate,'%') AS Kehadiran,COALESCE(r.action_label,'Belum dianalisis') AS Rekomendasi,a.assessment_date AS Tanggal FROM students s JOIN assessments a ON a.student_id=s.id LEFT JOIN recommendations r ON r.assessment_id=a.id ORDER BY s.class_name,s.name")->fetchAll(); if($type==='remedial')$rows=array_values(array_filter($rows,fn($r)=>$r['Rekomendasi']==='Remedial')); if($type==='pengayaan')$rows=array_values(array_filter($rows,fn($r)=>$r['Rekomendasi']==='Pengayaan')); if(($_GET['format']??'csv')==='pdf') exportPdfHtml($rows,'Laporan EduInsight AI'); exportCsv($rows,'laporan-eduinsight.csv');
